#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TensorMeta {
    pub name: String,
    pub dtype: String,
    pub shape: Vec<u64>,
    /// Offsets relative to the beginning of the SafeTensors data buffer.
    pub data_offsets: (u64, u64),
    /// Absolute byte offset in the file.
    pub file_offsets: (u64, u64),
}

impl TensorMeta {
    pub fn numel(&self) -> Option<u128> {
        self.shape
            .iter()
            .try_fold(1u128, |acc, &v| acc.checked_mul(v as u128))
    }

    pub fn byte_len(&self) -> u64 {
        self.data_offsets.1 - self.data_offsets.0
    }

    pub fn dtype_size(&self) -> Option<u64> {
        dtype_size(&self.dtype)
    }

    pub fn validate_size(&self) -> Result<()> {
        let Some(dtype_size) = self.dtype_size() else {
            return Ok(());
        };
        let Some(numel) = self.numel() else {
            return Err(anyhow!("tensor {} shape product overflows", self.name));
        };
        let expected = numel
            .checked_mul(dtype_size as u128)
            .ok_or_else(|| anyhow!("tensor {} byte size overflows", self.name))?;
        let got = self.byte_len() as u128;
        if expected != got {
            return Err(anyhow!(
                "tensor {} size mismatch: shape {:?} dtype {} expects {} bytes, header has {}",
                self.name,
                self.shape,
                self.dtype,
                expected,
                got
            ));
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QwenWeightPlacement {
    /// Load one full copy on each TP rank.
    Replicated,
    /// Slice along the given row-major tensor axis.
    TensorParallel { axis: usize },
    /// Routed expert tensor: place the whole expert on its EP owner first.
    ExpertWhole,
}

/// Qwen/Qwen-MoE default serving placement for Hugging Face-style tensor names.
///
/// Dense attention/MLP follows Megatron-style TP:
/// - q/k/v/gate/up: output dimension split (`axis=0` for `[out, in]`)
/// - o/down: input dimension split (`axis=1` for `[out, in]`)
///
/// Routed experts are deliberately reported as whole-expert placement because the
/// high-speed serving path should support EP separately from TP instead of blindly
/// slicing every expert across every GPU.
pub fn qwen_weight_placement(name: &str) -> QwenWeightPlacement {
    if is_qwen_routed_expert_weight(name) {
        return QwenWeightPlacement::ExpertWhole;
    }
    if name.ends_with(".q_proj.weight")
        || name.ends_with(".k_proj.weight")
        || name.ends_with(".v_proj.weight")
        || name.ends_with(".gate_proj.weight")
        || name.ends_with(".up_proj.weight")
        || name == "lm_head.weight"
        || name.ends_with(".lm_head.weight")
        || name.ends_with(".embed_tokens.weight")
    {
        QwenWeightPlacement::TensorParallel { axis: 0 }
    } else if name.ends_with(".o_proj.weight") || name.ends_with(".down_proj.weight") {
        QwenWeightPlacement::TensorParallel { axis: 1 }
    } else {
        QwenWeightPlacement::Replicated
    }
}

pub fn is_qwen_routed_expert_weight(name: &str) -> bool {
    name.contains(".experts.") && name.ends_with(".weight")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FileByteRange {
    pub begin: u64,
    pub end: u64,
}

impl FileByteRange {
    pub fn byte_len(self) -> u64 {
        self.end - self.begin
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AlignedReadWindow {
    pub range: FileByteRange,
    /// Bytes to skip from the aligned read start to reach the requested range.
    pub prefix_bytes: usize,
}

/// Expand a file byte range to an enclosing Direct-I/O-friendly aligned window.
///
/// SafeTensors tensor starts are usually not block-aligned because the JSON
/// header has arbitrary length. Direct-I/O loaders must read the enclosing
/// aligned window, then skip `prefix_bytes` before dense staging/SDMA upload.
pub fn aligned_read_window(range: FileByteRange, alignment: u64) -> Result<AlignedReadWindow> {
    if alignment == 0 || !alignment.is_power_of_two() {
        return Err(anyhow!("alignment must be a non-zero power of two"));
    }
    if range.begin > range.end {
        return Err(anyhow!("aligned read range is inverted"));
    }
    let begin = range.begin & !(alignment - 1);
    let end = if range.end == 0 {
        0
    } else {
        range
            .end
            .checked_add(alignment - 1)
            .ok_or_else(|| anyhow!("aligned read range end overflows"))?
            & !(alignment - 1)
    };
    Ok(AlignedReadWindow {
        range: FileByteRange { begin, end },
        prefix_bytes: (range.begin - begin) as usize,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CheckpointPayloadDirectReadWorkOrder {
    pub slot: usize,
    pub tensor: String,
    pub checkpoint_key: String,
    pub payload_source: String,
    pub payload_file_range: FileByteRange,
    pub aligned_read_window: AlignedReadWindow,
    pub payload_staging_offset: usize,
    pub aligned_read_bytes: usize,
    pub payload_bytes: usize,
    pub destination_offset_bytes: usize,
    pub destination_device_va: u64,
    pub destination_device_va_end: u64,
    pub dtype: DType,
    pub shape: Vec<usize>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CheckpointPayloadDirectReadPlan {
    pub target: &'static str,
    pub direct_io_alignment: u64,
    pub source_count: usize,
    pub slot_count: usize,
    pub work_order_count: usize,
    pub total_payload_bytes: usize,
    pub total_aligned_read_bytes: usize,
    pub max_staging_window_bytes: usize,
    pub live_execution_supported: bool,
    pub work_orders: Vec<CheckpointPayloadDirectReadWorkOrder>,
}

impl CheckpointPayloadDirectReadPlan {
    /// Build CPU-only direct-read work orders from a bound model API payload plan.
    ///
    /// The result tells a future live loader which aligned file windows to read,
    /// where the payload starts inside each staging window, and which device VA
    /// each payload span would target. It does not open files, allocate staging
    /// memory, copy to VRAM, submit SDMA, or execute kernels.
    pub fn from_checkpoint_payload_binding_plan(
        payload_plan: &ModelRuntimeCheckpointPayloadBindingPlan,
        direct_io_alignment: u64,
    ) -> Result<Self> {
        payload_plan.assert_checkpoint_payload_bound()?;
        if direct_io_alignment == 0 || !direct_io_alignment.is_power_of_two() {
            return Err(anyhow!(
                "direct I/O alignment must be a non-zero power of two"
            ));
        }

        let mut work_orders = Vec::new();
        let mut sources = BTreeSet::<String>::new();
        let mut slots = BTreeSet::new();
        let mut total_payload_bytes = 0usize;
        let mut total_aligned_read_bytes = 0usize;
        let mut max_staging_window_bytes = 0usize;

        for entry in &payload_plan.entries {
            let slot_device_end = entry.device_va_end.ok_or_else(|| {
                anyhow!(
                    "slot {} {} has no destination VA end",
                    entry.slot,
                    entry.tensor
                )
            })?;
            let mut destination_offset_bytes = 0usize;
            slots.insert(entry.slot);
            for binding in &entry.payload_bindings {
                if binding.payload_bytes == 0 {
                    return Err(anyhow!(
                        "checkpoint payload {} for {} has zero bytes",
                        binding.checkpoint_key,
                        binding.tensor
                    ));
                }
                let payload_end = binding
                    .payload_offset
                    .checked_add(binding.payload_bytes as u64)
                    .ok_or_else(|| {
                        anyhow!(
                            "checkpoint payload {} file range overflows",
                            binding.checkpoint_key
                        )
                    })?;
                let payload_file_range = FileByteRange {
                    begin: binding.payload_offset,
                    end: payload_end,
                };
                let aligned_read_window =
                    aligned_read_window(payload_file_range, direct_io_alignment)?;
                let aligned_read_bytes = usize::try_from(aligned_read_window.range.byte_len())
                    .map_err(|_| {
                        anyhow!(
                            "checkpoint payload {} aligned read window exceeds usize",
                            binding.checkpoint_key
                        )
                    })?;
                let destination_device_va = entry
                    .device_va
                    .checked_add(destination_offset_bytes as u64)
                    .ok_or_else(|| {
                        anyhow!(
                            "checkpoint payload {} destination VA overflows",
                            binding.checkpoint_key
                        )
                    })?;
                let destination_device_va_end = destination_device_va
                    .checked_add(binding.payload_bytes as u64)
                    .ok_or_else(|| {
                        anyhow!(
                            "checkpoint payload {} destination VA end overflows",
                            binding.checkpoint_key
                        )
                    })?;
                if destination_device_va_end > slot_device_end {
                    return Err(anyhow!(
                        "checkpoint payload {} destination end 0x{destination_device_va_end:016x} exceeds slot {} end 0x{slot_device_end:016x}",
                        binding.checkpoint_key,
                        entry.slot
                    ));
                }

                sources.insert(binding.payload_source.clone());
                total_payload_bytes = checked_add_usize(
                    total_payload_bytes,
                    binding.payload_bytes,
                    "checkpoint direct-read payload bytes",
                )?;
                total_aligned_read_bytes = checked_add_usize(
                    total_aligned_read_bytes,
                    aligned_read_bytes,
                    "checkpoint direct-read aligned bytes",
                )?;
                max_staging_window_bytes = max_staging_window_bytes.max(aligned_read_bytes);
                work_orders.push(CheckpointPayloadDirectReadWorkOrder {
                    slot: entry.slot,
                    tensor: entry.tensor.to_string(),
                    checkpoint_key: binding.checkpoint_key.clone(),
                    payload_source: binding.payload_source.clone(),
                    payload_file_range,
                    aligned_read_window,
                    payload_staging_offset: aligned_read_window.prefix_bytes,
                    aligned_read_bytes,
                    payload_bytes: binding.payload_bytes,
                    destination_offset_bytes,
                    destination_device_va,
                    destination_device_va_end,
                    dtype: binding.dtype,
                    shape: binding.shape.clone(),
                });
                destination_offset_bytes = checked_add_usize(
                    destination_offset_bytes,
                    binding.payload_bytes,
                    "checkpoint direct-read destination offset",
                )?;
            }
            if destination_offset_bytes != entry.storage_bytes {
                return Err(anyhow!(
                    "slot {} {} direct-read payload bytes {} != storage bytes {}",
                    entry.slot,
                    entry.tensor,
                    destination_offset_bytes,
                    entry.storage_bytes
                ));
            }
        }

        let plan = Self {
            target: payload_plan.target,
            direct_io_alignment,
            source_count: sources.len(),
            slot_count: slots.len(),
            work_order_count: work_orders.len(),
            total_payload_bytes,
            total_aligned_read_bytes,
            max_staging_window_bytes,
            live_execution_supported: payload_plan.live_execution_supported,
            work_orders,
        };
        plan.assert_consistent()?;
        Ok(plan)
    }

    pub fn assert_consistent(&self) -> Result<()> {
        let mut issues = Vec::new();
        if self.direct_io_alignment == 0 || !self.direct_io_alignment.is_power_of_two() {
            issues.push("direct I/O alignment is not a non-zero power of two".to_string());
        }
        if self.work_order_count != self.work_orders.len() {
            issues.push(format!(
                "work order count {} != rows {}",
                self.work_order_count,
                self.work_orders.len()
            ));
        }
        if self.live_execution_supported {
            issues.push("live execution support is unexpectedly enabled".to_string());
        }

        let mut sources = BTreeSet::new();
        let mut slots = BTreeSet::new();
        let mut total_payload_bytes = 0usize;
        let mut total_aligned_read_bytes = 0usize;
        let mut max_staging_window_bytes = 0usize;
        for order in &self.work_orders {
            sources.insert(order.payload_source.as_str());
            slots.insert(order.slot);
            if order.payload_file_range.byte_len() != order.payload_bytes as u64 {
                issues.push(format!(
                    "{} file range bytes {} != payload bytes {}",
                    order.checkpoint_key,
                    order.payload_file_range.byte_len(),
                    order.payload_bytes
                ));
            }
            match aligned_read_window(order.payload_file_range, self.direct_io_alignment) {
                Ok(expected) if expected == order.aligned_read_window => {}
                Ok(expected) => issues.push(format!(
                    "{} aligned window {:?} != expected {:?}",
                    order.checkpoint_key, order.aligned_read_window, expected
                )),
                Err(err) => issues.push(format!(
                    "{} aligned window error: {err}",
                    order.checkpoint_key
                )),
            }
            if order.payload_staging_offset != order.aligned_read_window.prefix_bytes {
                issues.push(format!(
                    "{} staging offset {} != aligned prefix {}",
                    order.checkpoint_key,
                    order.payload_staging_offset,
                    order.aligned_read_window.prefix_bytes
                ));
            }
            let aligned_window_bytes =
                match usize::try_from(order.aligned_read_window.range.byte_len()) {
                    Ok(bytes) => bytes,
                    Err(_) => {
                        issues.push(format!(
                            "{} aligned read window exceeds usize",
                            order.checkpoint_key
                        ));
                        continue;
                    }
                };
            if order.aligned_read_bytes != aligned_window_bytes {
                issues.push(format!(
                    "{} aligned read bytes {} != window bytes {}",
                    order.checkpoint_key, order.aligned_read_bytes, aligned_window_bytes
                ));
            }
            match order
                .payload_staging_offset
                .checked_add(order.payload_bytes)
            {
                Some(end) if end <= order.aligned_read_bytes => {}
                Some(end) => issues.push(format!(
                    "{} staging payload end {} exceeds aligned read bytes {}",
                    order.checkpoint_key, end, order.aligned_read_bytes
                )),
                None => issues.push(format!(
                    "{} staging payload span overflows",
                    order.checkpoint_key
                )),
            }
            match order
                .destination_device_va
                .checked_add(order.payload_bytes as u64)
            {
                Some(end) if end == order.destination_device_va_end => {}
                Some(end) => issues.push(format!(
                    "{} destination end 0x{:016x} != expected 0x{end:016x}",
                    order.checkpoint_key, order.destination_device_va_end
                )),
                None => issues.push(format!(
                    "{} destination device VA span overflows",
                    order.checkpoint_key
                )),
            }
            total_payload_bytes = checked_add_usize(
                total_payload_bytes,
                order.payload_bytes,
                "checkpoint direct-read payload bytes",
            )?;
            total_aligned_read_bytes = checked_add_usize(
                total_aligned_read_bytes,
                order.aligned_read_bytes,
                "checkpoint direct-read aligned bytes",
            )?;
            max_staging_window_bytes = max_staging_window_bytes.max(order.aligned_read_bytes);
        }
        if sources.len() != self.source_count {
            issues.push(format!(
                "source count {} != distinct sources {}",
                self.source_count,
                sources.len()
            ));
        }
        if slots.len() != self.slot_count {
            issues.push(format!(
                "slot count {} != distinct slots {}",
                self.slot_count,
                slots.len()
            ));
        }
        if total_payload_bytes != self.total_payload_bytes {
            issues.push(format!(
                "payload bytes {total_payload_bytes} != plan {}",
                self.total_payload_bytes
            ));
        }
        if total_aligned_read_bytes != self.total_aligned_read_bytes {
            issues.push(format!(
                "aligned read bytes {total_aligned_read_bytes} != plan {}",
                self.total_aligned_read_bytes
            ));
        }
        if max_staging_window_bytes != self.max_staging_window_bytes {
            issues.push(format!(
                "max staging window {max_staging_window_bytes} != plan {}",
                self.max_staging_window_bytes
            ));
        }

        if issues.is_empty() {
            Ok(())
        } else {
            Err(anyhow!(
                "checkpoint payload direct-read plan for {} has {} issue(s): {}",
                self.target,
                issues.len(),
                issues.join("; ")
            ))
        }
    }

    pub fn staging_batch_plan(
        &self,
        staging_slot_count: usize,
    ) -> Result<CheckpointPayloadDirectReadStagingPlan> {
        CheckpointPayloadDirectReadStagingPlan::from_direct_read_plan(self, staging_slot_count)
    }
}

