        push_checkpoint_payload_receipt_line(&mut lines, "source_count", self.source_count);
        push_checkpoint_payload_receipt_line(&mut lines, "slot_count", self.slot_count);
        push_checkpoint_payload_receipt_line(&mut lines, "batch_count", self.batch_count);
        push_checkpoint_payload_receipt_line(&mut lines, "copy_count", self.copy_count);
