fn checkpoint_payload_upload_prerequisite_rows(
) -> Vec<CheckpointPayloadHostToDeviceUploadPrerequisite> {
    [
        (
            "host_staging_pin",
            "pin_host_staging_pages",
            "CheckpointPayloadHostStagingPinRequest",
        ),
        (
            "destination_vram_residency",
            "query_destination_device_residency",
            "CheckpointPayloadDestinationResidencyQueryRequest",
        ),
        (
            "sdma_queue_reservation",
            "reserve_sdma_queue_slots",
            "CheckpointPayloadSdmaQueueReservationInput",
        ),
        (
            "copy_completion_signal_binding",
            "bind_copy_completion_signal",
            "CheckpointPayloadCopyCompletionSignalBindingInput",
        ),
        (
            "upload_packet_materialization",
            "materialize_sdma_copy_packets",
            "CheckpointPayloadSdmaCopyPacketMaterializationInput",
        ),
        (
            "upload_packet_validation",
            "validate_sdma_copy_packets",
            "CheckpointPayloadSdmaCopyPacketValidationInput",
        ),
        (
            "cache_visibility_policy",
            "select_cache_visibility_policy",
            "CheckpointPayloadCacheVisibilityPolicyInput",
        ),
        (
            "upload_completion_synchronization",
            "plan_upload_completion_synchronization",
            "CheckpointPayloadUploadSynchronizationPlanInput",
        ),
    ]
    .into_iter()
    .enumerate()
    .map(
        |(step_index, (requirement, next_action, next_action_input))| {
            CheckpointPayloadHostToDeviceUploadPrerequisite {
                step_index,
                requirement,
                next_action,
                next_action_input,
                prerequisite_satisfied: false,
            }
        },
    )
    .collect()
}

fn checkpoint_payload_upload_handoff_receipt_kind_for_input(
    next_action_input: &str,
) -> Option<&'static str> {
    match next_action_input {
        "CheckpointPayloadHostStagingPinRequest" => {
            Some("checkpoint_payload_host_staging_pin_request")
        }
        "CheckpointPayloadDestinationResidencyQueryRequest" => {
            Some("checkpoint_payload_destination_residency_query_request")
        }
        "CheckpointPayloadSdmaQueueReservationInput" => {
            Some("checkpoint_payload_sdma_queue_reservation_input")
        }
        "CheckpointPayloadCopyCompletionSignalBindingInput" => {
            Some("checkpoint_payload_copy_completion_signal_binding_input")
        }
        "CheckpointPayloadSdmaCopyPacketMaterializationInput" => {
            Some("checkpoint_payload_sdma_copy_packet_materialization_input")
        }
        "CheckpointPayloadSdmaCopyPacketValidationInput" => {
            Some("checkpoint_payload_sdma_copy_packet_validation_input")
        }
        "CheckpointPayloadCacheVisibilityPolicyInput" => {
            Some("checkpoint_payload_cache_visibility_policy_input")
        }
        "CheckpointPayloadUploadSynchronizationPlanInput" => {
            Some("checkpoint_payload_upload_synchronization_plan_input")
        }
        _ => None,
    }
}

fn checkpoint_payload_upload_handoff_input_receipt(
    prerequisite_plan: &CheckpointPayloadHostToDeviceUploadPrerequisitePlan,
    input_index: usize,
    receipt_kind: &'static str,
    receipt_lines: Vec<String>,
) -> Result<CheckpointPayloadHostToDeviceUploadRuntimeHandoffInputReceipt> {
    let actual_receipt_kind = receipt_lines
        .first()
        .and_then(|line| line.strip_prefix("receipt.kind="))
        .ok_or_else(|| {
            anyhow!(
                "checkpoint upload handoff input {} receipt is missing receipt.kind line",
                input_index
            )
        })?;
    if actual_receipt_kind != receipt_kind {
        return Err(anyhow!(
            "checkpoint upload handoff input {} receipt text kind {} != declared {}",
            input_index,
            actual_receipt_kind,
            receipt_kind
        ));
    }
    let prerequisite = prerequisite_plan
        .prerequisites
        .get(input_index)
        .ok_or_else(|| anyhow!("checkpoint upload handoff missing prerequisite {input_index}"))?;
    let expected_receipt_kind =
        checkpoint_payload_upload_handoff_receipt_kind_for_input(prerequisite.next_action_input)
            .ok_or_else(|| {
                anyhow!(
            "checkpoint upload handoff prerequisite {} input {} has no receipt kind mapping",
            prerequisite.requirement,
            prerequisite.next_action_input
        )
            })?;
    if receipt_kind != expected_receipt_kind {
        return Err(anyhow!(
            "checkpoint upload handoff input {} receipt kind {} != expected {}",
            input_index,
            receipt_kind,
            expected_receipt_kind
        ));
    }
    let receipt_line_count = receipt_lines.len();
    Ok(
        CheckpointPayloadHostToDeviceUploadRuntimeHandoffInputReceipt {
            input_index,
            requirement: prerequisite.requirement,
            next_action: prerequisite.next_action,
            next_action_input: prerequisite.next_action_input,
            receipt_kind,
            receipt_fingerprint: checkpoint_payload_receipt_fingerprint_from_lines(&receipt_lines),
            receipt_line_count,
        },
    )
}

fn checkpoint_host_staging_pin_page_spans(
    ranges: &[CheckpointPayloadHostStagingPinRange],
    host_page_size_bytes: usize,
) -> Result<Vec<CheckpointPayloadHostStagingPinPageSpan>> {
    if host_page_size_bytes == 0 || !host_page_size_bytes.is_power_of_two() {
        return Err(anyhow!(
            "checkpoint host-staging pin page size must be a non-zero power of two"
        ));
    }

    let mut page_spans = Vec::<CheckpointPayloadHostStagingPinPageSpan>::new();
    for (range_index, range) in ranges.iter().enumerate() {
        let page_offset_begin = align_down_usize(range.pin_offset_begin, host_page_size_bytes);
        let page_offset_end = align_up_usize(
            range.pin_offset_end,
            host_page_size_bytes,
            "checkpoint host-staging pin page span",
        )?;
        let page_bytes = page_offset_end
            .checked_sub(page_offset_begin)
            .ok_or_else(|| anyhow!("checkpoint host-staging pin page span underflows"))?;
        if let Some(last) = page_spans.last_mut() {
            if page_offset_begin <= last.page_offset_end {
                last.pin_range_end_index_exclusive = range_index + 1;
                last.pin_range_count = last.pin_range_count.checked_add(1).ok_or_else(|| {
                    anyhow!("checkpoint host-staging pin page range count overflows")
                })?;
                last.page_offset_end = last.page_offset_end.max(page_offset_end);
                last.page_bytes = last
                    .page_offset_end
                    .checked_sub(last.page_offset_begin)
                    .ok_or_else(|| {
                        anyhow!("checkpoint host-staging merged page span underflows")
                    })?;
                last.covers_pin_ranges = true;
                continue;
            }
        }
        page_spans.push(CheckpointPayloadHostStagingPinPageSpan {
            page_span_index: page_spans.len(),
            pin_range_begin_index: range_index,
            pin_range_end_index_exclusive: range_index + 1,
            pin_range_count: 1,
            page_offset_begin,
            page_offset_end,
            page_bytes,
            covers_pin_ranges: true,
        });
        if page_bytes == 0 {
            return Err(anyhow!(
                "checkpoint host-staging pin page span for range {range_index} is empty"
            ));
        }
    }
    Ok(page_spans)
}

#[allow(clippy::too_many_arguments)]
fn push_checkpoint_payload_upload_wave(
    waves: &mut Vec<CheckpointPayloadHostToDeviceUploadWave>,
    slot_epochs: &mut BTreeMap<usize, usize>,
    total_copy_bytes: &mut usize,
    max_wave_copy_count: &mut usize,
    max_wave_copy_bytes: &mut usize,
    max_wave_host_staging_span_bytes: &mut usize,
    batch_index: usize,
    source: &str,
    staging_slot: usize,
    copy_begin_index: usize,
    copy_count: usize,
    copy_bytes: usize,
    host_staging_offset_begin: usize,
    host_staging_offset_end: usize,
    destination_device_va_min: u64,
    destination_device_va_max_end: u64,
) -> Result<()> {
    if copy_count == 0 {
        return Err(anyhow!(
            "checkpoint upload schedule batch {} has no copies",
            batch_index
        ));
    }
    let host_staging_span_bytes = host_staging_offset_end
        .checked_sub(host_staging_offset_begin)
        .ok_or_else(|| anyhow!("checkpoint upload wave host staging span underflows"))?;
    let staging_slot_epoch = *slot_epochs.get(&staging_slot).unwrap_or(&0usize);
    slot_epochs.insert(staging_slot, staging_slot_epoch + 1);
    *total_copy_bytes = checked_add_usize(
        *total_copy_bytes,
        copy_bytes,
        "checkpoint upload schedule copy bytes",
    )?;
    *max_wave_copy_count = (*max_wave_copy_count).max(copy_count);
    *max_wave_copy_bytes = (*max_wave_copy_bytes).max(copy_bytes);
    *max_wave_host_staging_span_bytes =
        (*max_wave_host_staging_span_bytes).max(host_staging_span_bytes);
    waves.push(CheckpointPayloadHostToDeviceUploadWave {
        wave_index: waves.len(),
        batch_index,
        source: source.to_string(),
        staging_slot,
        staging_slot_epoch,
        copy_begin_index,
        copy_count,
        copy_bytes,
        host_staging_offset_begin,
        host_staging_offset_end,
        host_staging_span_bytes,
        destination_device_va_min,
        destination_device_va_max_end,
    });
    Ok(())
}

#[derive(Debug, Clone)]
struct PendingCheckpointPayloadDirectReadBatch {
    source: String,
    aligned_file_range: FileByteRange,
    pieces: Vec<CheckpointPayloadDirectReadStagingPiece>,
}

impl PendingCheckpointPayloadDirectReadBatch {
    fn push_piece(
        &mut self,
        work_order_index: usize,
        order: &CheckpointPayloadDirectReadWorkOrder,
    ) -> Result<()> {
        let payload_staging_begin =
            usize::try_from(order.payload_file_range.begin - self.aligned_file_range.begin)
                .map_err(|_| {
                    anyhow!(
                        "checkpoint payload {} staging offset exceeds usize",
                        order.checkpoint_key
                    )
                })?;
        self.pieces.push(CheckpointPayloadDirectReadStagingPiece {
            work_order_index,
            slot: order.slot,
            tensor: order.tensor.clone(),
            checkpoint_key: order.checkpoint_key.clone(),
            payload_staging_begin,
            payload_bytes: order.payload_bytes,
            destination_offset_bytes: order.destination_offset_bytes,
            destination_device_va: order.destination_device_va,
            destination_device_va_end: order.destination_device_va_end,
        });
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TensorSlicePlan {
    pub tensor: String,
    pub axis: usize,
    pub rank: usize,
    pub parts: usize,
    pub source_shape: Vec<u64>,
    pub local_shape: Vec<u64>,
    pub ranges: Vec<FileByteRange>,
}

impl TensorSlicePlan {
    pub fn total_bytes(&self) -> u64 {
        self.ranges.iter().map(|r| r.byte_len()).sum()
    }

    pub fn is_contiguous(&self) -> bool {
        self.ranges.len() == 1
    }
}

/// Plan exact file byte ranges for one tensor-parallel slice of a row-major tensor.
///
/// `axis=0` on `[out, in]` weights yields one contiguous range (column-parallel
/// linear in Megatron terminology). `axis=1` yields one range per output row
/// (row-parallel linear), which is intentionally explicit so the next loader
/// stage can choose between scatter reads, coalesced staging, or file-layout
/// conversion.
pub fn plan_tensor_parallel_slice(
    meta: &TensorMeta,
    axis: usize,
    rank: usize,
    parts: usize,
    block_multiple: Option<u64>,
) -> Result<TensorSlicePlan> {
    if parts == 0 {
        return Err(anyhow!("tensor-parallel parts must be non-zero"));
    }
    if rank >= parts {
        return Err(anyhow!(
            "tensor-parallel rank {rank} out of range for {parts} parts"
        ));
    }
    if axis >= meta.shape.len() {
        return Err(anyhow!(
            "tensor {} axis {axis} out of range for shape {:?}",
            meta.name,
            meta.shape
        ));
    }
    let elem_size = meta.dtype_size().ok_or_else(|| {
        anyhow!(
            "tensor {} dtype {} has no fixed byte size",
            meta.name,
            meta.dtype
        )
    })?;
    let axis_len = meta.shape[axis];
    if axis_len == 0 {
        return Err(anyhow!("tensor {} axis {axis} has zero length", meta.name));
    }
    if !axis_len.is_multiple_of(parts as u64) {
        return Err(anyhow!(
            "tensor {} axis {axis} length {} is not divisible by tp parts {}",
            meta.name,
            axis_len,
            parts
        ));
    }
    let local_axis = axis_len / parts as u64;
    if let Some(block) = block_multiple {
        if block != 0 && !local_axis.is_multiple_of(block) {
            return Err(anyhow!(
                "tensor {} local axis length {} is not divisible by block multiple {}",
                meta.name,
                local_axis,
                block
            ));
        }
    }

    let prefix = product_u64(&meta.shape[..axis], "slice prefix")?;
    let suffix = product_u64(&meta.shape[axis + 1..], "slice suffix")?;
    let start = (rank as u64)
        .checked_mul(local_axis)
        .ok_or_else(|| anyhow!("tensor {} slice start overflows", meta.name))?;
    let end = start + local_axis;
    let mut local_shape = meta.shape.clone();
    local_shape[axis] = local_axis;
    let mut ranges = Vec::with_capacity(
        prefix
            .try_into()
            .map_err(|_| anyhow!("tensor {} slice prefix too large", meta.name))?,
    );
    for p in 0..prefix {
        let row_base = p
            .checked_mul(axis_len)
            .and_then(|v| v.checked_mul(suffix))
            .ok_or_else(|| anyhow!("tensor {} slice base overflows", meta.name))?;
        let begin_elem = row_base
            .checked_add(
                start
                    .checked_mul(suffix)
                    .ok_or_else(|| anyhow!("tensor {} slice begin overflows", meta.name))?,
            )
            .ok_or_else(|| anyhow!("tensor {} slice begin overflows", meta.name))?;
        let end_elem = row_base
            .checked_add(
                end.checked_mul(suffix)
                    .ok_or_else(|| anyhow!("tensor {} slice end overflows", meta.name))?,
            )
            .ok_or_else(|| anyhow!("tensor {} slice end overflows", meta.name))?;
        let begin = meta
            .file_offsets
            .0
            .checked_add(
                begin_elem
                    .checked_mul(elem_size)
                    .ok_or_else(|| anyhow!("tensor {} byte offset overflows", meta.name))?,
            )
            .ok_or_else(|| anyhow!("tensor {} byte offset overflows", meta.name))?;
        let end = meta
            .file_offsets
            .0
            .checked_add(
                end_elem
                    .checked_mul(elem_size)
                    .ok_or_else(|| anyhow!("tensor {} byte offset overflows", meta.name))?,
            )
            .ok_or_else(|| anyhow!("tensor {} byte offset overflows", meta.name))?;
        ranges.push(FileByteRange { begin, end });
    }

    let plan = TensorSlicePlan {
        tensor: meta.name.clone(),
        axis,
        rank,
        parts,
        source_shape: meta.shape.clone(),
        local_shape,
        ranges,
    };
    let expected = meta.byte_len() / parts as u64;
    if plan.total_bytes() != expected {
        return Err(anyhow!(
            "tensor {} slice byte accounting mismatch: planned {} expected {}",
            meta.name,
            plan.total_bytes(),
            expected
        ));
    }
    Ok(plan)
}

/// Read the planned TP slice ranges from `path` into a dense local tensor buffer.
///
/// For contiguous axis-0 slices this is one read. For row-parallel axis-1 slices
/// this gathers one file range per outer row and packs them densely in local
/// row-major order, exactly matching `TensorSlicePlan::local_shape`.
pub fn materialize_slice_from_file(
    path: impl AsRef<Path>,
    plan: &TensorSlicePlan,
) -> Result<Vec<u8>> {
    let file = File::open(path.as_ref())
        .with_context(|| format!("opening {}", path.as_ref().display()))?;
    materialize_slice_from_file_handle(&file, plan)
}

pub fn materialize_slice_from_file_handle(file: &File, plan: &TensorSlicePlan) -> Result<Vec<u8>> {
    let total = usize::try_from(plan.total_bytes())
        .with_context(|| format!("tensor {} slice exceeds usize", plan.tensor))?;
    let mut out = vec![0u8; total];
    let mut cursor = 0usize;
    for range in &plan.ranges {
        let n = usize::try_from(range.byte_len())
            .with_context(|| format!("tensor {} range exceeds usize", plan.tensor))?;
        read_exact_at(file, range.begin, &mut out[cursor..cursor + n]).with_context(|| {
            format!(
                "reading tensor {} at file range {}..{}",
                plan.tensor, range.begin, range.end
            )
        })?;
        cursor += n;
    }
    Ok(out)
}

pub fn materialize_slice_from_file_direct_aligned(
    path: impl AsRef<Path>,
    plan: &TensorSlicePlan,
    alignment: u64,
) -> Result<Vec<u8>> {
    if alignment == 0 || !alignment.is_power_of_two() {
        return Err(anyhow!(
            "direct I/O alignment must be a non-zero power of two"
        ));
    }
    let path = path.as_ref();
    let direct = OpenOptions::new()
        .read(true)
        .custom_flags(LINUX_O_DIRECT)
        .open(path)
        .with_context(|| format!("opening {} with O_DIRECT", path.display()))?;
    let buffered = File::open(path)
        .with_context(|| format!("opening {} for buffered fallback", path.display()))?;
    let file_len = direct
        .metadata()
        .with_context(|| format!("stat {}", path.display()))?
        .len();
    materialize_slice_from_file_handle_direct_aligned(&direct, &buffered, file_len, plan, alignment)
}

fn materialize_slice_from_file_handle_direct_aligned(
    direct: &File,
    buffered: &File,
    file_len: u64,
    plan: &TensorSlicePlan,
    alignment: u64,
) -> Result<Vec<u8>> {
    let total = usize::try_from(plan.total_bytes())
        .with_context(|| format!("tensor {} slice exceeds usize", plan.tensor))?;
    let mut out = vec![0u8; total];
    let mut cursor = 0usize;
    let align = usize::try_from(alignment).map_err(|_| anyhow!("alignment exceeds usize"))?;
    for range in &plan.ranges {
        let n = usize::try_from(range.byte_len())
            .with_context(|| format!("tensor {} range exceeds usize", plan.tensor))?;
        let window = aligned_read_window(*range, alignment)?;
        if window.range.end <= file_len {
            let win_len = usize::try_from(window.range.byte_len())
                .with_context(|| format!("tensor {} aligned range exceeds usize", plan.tensor))?;
            let mut tmp = AlignedBuffer::new(win_len, align)?;
            read_exact_at(direct, window.range.begin, tmp.as_mut_slice()).with_context(|| {
                format!(
                    "direct-reading tensor {} at aligned file range {}..{}",
                    plan.tensor, window.range.begin, window.range.end
                )
            })?;
            let start = window.prefix_bytes;
            out[cursor..cursor + n].copy_from_slice(&tmp.as_mut_slice()[start..start + n]);
        } else {
            read_exact_at(buffered, range.begin, &mut out[cursor..cursor + n]).with_context(
                || {
                    format!(
                        "buffered tail fallback for tensor {} at file range {}..{}",
                        plan.tensor, range.begin, range.end
                    )
                },
            )?;
        }
        cursor += n;
    }
    Ok(out)
}

fn read_exact_at(file: &File, mut offset: u64, mut dst: &mut [u8]) -> Result<()> {
    while !dst.is_empty() {
        let n = file.read_at(dst, offset)?;
        if n == 0 {
            return Err(
                std::io::Error::new(ErrorKind::UnexpectedEof, "short positional read").into(),
            );
        }
        offset += n as u64;
        dst = &mut dst[n..];
    }
    Ok(())
}

fn checkpoint_host_page_size_bytes() -> Result<usize> {
    let page_size = unsafe { libc::sysconf(libc::_SC_PAGESIZE) };
    if page_size <= 0 {
        return Err(anyhow!(
            "failed to query host page size for checkpoint mmap"
        ));
    }
    let page_size = usize::try_from(page_size)
        .map_err(|_| anyhow!("host page size exceeds usize for checkpoint mmap"))?;
    if !page_size.is_power_of_two() {
        return Err(anyhow!(
            "host page size {page_size} is not a power of two for checkpoint mmap"
        ));
    }
    Ok(page_size)
}

fn align_down_u64(value: u64, alignment: u64) -> u64 {
    debug_assert!(alignment.is_power_of_two());
    value & !(alignment - 1)
}

struct ReadOnlyFileMapping {
    ptr: NonNull<u8>,
    len: usize,
}

impl ReadOnlyFileMapping {
    fn map(file: &File, offset: u64, len: usize) -> Result<Self> {
        if len == 0 {
            return Err(anyhow!("checkpoint mmap length must be non-zero"));
        }
        let offset = libc::off_t::try_from(offset)
            .map_err(|_| anyhow!("checkpoint mmap offset exceeds off_t"))?;
        let raw = unsafe {
            libc::mmap(
                std::ptr::null_mut(),
                len,
                libc::PROT_READ,
                libc::MAP_PRIVATE,
                file.as_raw_fd(),
                offset,
            )
        };
        if raw == libc::MAP_FAILED {
            return Err(std::io::Error::last_os_error().into());
        }
        let ptr = NonNull::new(raw.cast::<u8>())
            .ok_or_else(|| anyhow!("checkpoint mmap returned a null pointer"))?;
        Ok(Self { ptr, len })
    }

    fn as_slice(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr.as_ptr(), self.len) }
    }
}

impl Drop for ReadOnlyFileMapping {
    fn drop(&mut self) {
        unsafe {
            let rc = libc::munmap(self.ptr.as_ptr().cast(), self.len);
            debug_assert_eq!(rc, 0);
        }
    }
}

struct AlignedBuffer {
    ptr: NonNull<u8>,
    len: usize,
    layout: Layout,
}

impl AlignedBuffer {
    fn new(len: usize, alignment: usize) -> Result<Self> {
        if alignment == 0 || !alignment.is_power_of_two() {
            return Err(anyhow!("alignment must be a non-zero power of two"));
        }
        let layout = Layout::from_size_align(len.max(1), alignment)
            .map_err(|_| anyhow!("invalid aligned buffer layout"))?;
        let raw = unsafe { alloc(layout) };
        let ptr = NonNull::new(raw).ok_or_else(|| anyhow!("aligned buffer allocation failed"))?;
        Ok(Self { ptr, len, layout })
    }

    fn as_mut_slice(&mut self) -> &mut [u8] {
        unsafe { std::slice::from_raw_parts_mut(self.ptr.as_ptr(), self.len) }
    }
}

impl Drop for AlignedBuffer {
    fn drop(&mut self) {
        unsafe {
            dealloc(self.ptr.as_ptr(), self.layout);
        }
    }
}

/// Upload bytes through a host-visible staging buffer into VRAM with raw KFD SDMA.
pub fn upload_bytes_to_vram_sdma(
    dev: &GpuDevice,
    bytes: &[u8],
    timeout: Duration,
) -> Result<DeviceBuffer> {
    let alloc_len = bytes.len().max(1);
    let mut staging = dev.alloc(alloc_len)?;
    let dst = dev.alloc_device(alloc_len)?;
    unsafe {
        staging.as_mut_slice()[..bytes.len()].copy_from_slice(bytes);
    }
    let mut sdma = crate::SdmaQueue::new(dev.kfd(), dev.node_id())?;
    sdma.copy(staging.va(), dst.va(), bytes.len(), timeout)?;
    Ok(dst)
}

pub struct WeightSdmaUploader {
    staging: DeviceBuffer,
    dst: DeviceBuffer,
    fences: DeviceBuffer,
    sdma: crate::SdmaQueue,
    staging_capacity: usize,
    dst_capacity: usize,
    fence_slots: usize,
}

impl WeightSdmaUploader {
    pub fn new(dev: &GpuDevice, capacity: usize) -> Result<Self> {
        Self::new_with_capacities(dev, capacity, capacity)
    }

    pub fn new_with_capacities(
        dev: &GpuDevice,
        staging_capacity: usize,
        dst_capacity: usize,
    ) -> Result<Self> {
        if staging_capacity == 0 || dst_capacity == 0 {
            return Err(anyhow!(
                "reusable weight uploader capacities must be non-zero"
            ));
        }
        let mut fences = dev.alloc(4096)?;
        unsafe {
            fences.as_mut_slice().fill(0);
        }
        Ok(Self {
            staging: dev.alloc(staging_capacity)?,
            dst: dev.alloc_device(dst_capacity)?,
            fences,
            sdma: crate::SdmaQueue::new(dev.kfd(), dev.node_id())?,
            staging_capacity,
            dst_capacity,
            fence_slots: 1024,
        })
    }

    pub fn upload(&mut self, bytes: &[u8], timeout: Duration) -> Result<()> {
        if bytes.len() > self.staging_capacity || bytes.len() > self.dst_capacity {
            return Err(anyhow!(
                "reusable weight uploader capacity staging={} dst={} is smaller than upload {}",
                self.staging_capacity,
                self.dst_capacity,
                bytes.len()
            ));
        }
        unsafe {
            self.staging.as_mut_slice()[..bytes.len()].copy_from_slice(bytes);
        }
        self.sdma
            .copy(self.staging.va(), self.dst.va(), bytes.len(), timeout)
    }

    pub fn read_into_staging_at(&mut self, file: &File, offset: u64, bytes: usize) -> Result<()> {
        self.read_into_staging_at_offset(file, offset, 0, bytes)
    }

    pub fn read_into_staging_at_offset(
        &mut self,
        file: &File,
        file_offset: u64,
        staging_offset: usize,
        bytes: usize,
    ) -> Result<()> {
        if staging_offset
            .checked_add(bytes)
            .is_none_or(|end| end > self.staging_capacity)
        {
            return Err(anyhow!(
                "reusable weight uploader read out of bounds: staging_offset={} bytes={} staging_capacity={}",
                staging_offset,
                bytes,
                self.staging_capacity
            ));
        }
        let dst =
            unsafe { &mut self.staging.as_mut_slice()[staging_offset..staging_offset + bytes] };
        read_exact_at(file, file_offset, dst)
    }

    pub fn copy_staging_to_dst(
        &mut self,
        staging_offset: usize,
        dst_offset: usize,
        bytes: usize,
        timeout: Duration,
    ) -> Result<()> {
        if staging_offset
            .checked_add(bytes)
            .is_none_or(|end| end > self.staging_capacity)
            || dst_offset
                .checked_add(bytes)
                .is_none_or(|end| end > self.dst_capacity)
        {
            return Err(anyhow!(
                "reusable weight uploader copy out of bounds: staging_offset={} dst_offset={} bytes={} staging_capacity={} dst_capacity={}",
                staging_offset,
                dst_offset,
                bytes,
                self.staging_capacity,
                self.dst_capacity
            ));
        }
        self.sdma.copy(
            self.staging.va() + staging_offset as u64,
            self.dst.va() + dst_offset as u64,
            bytes,
            timeout,
        )
    }

    pub fn copy_staging_to_dst_fenced_async(
        &mut self,
        staging_offset: usize,
        dst_offset: usize,
        bytes: usize,
        fence_slot: usize,
        fence_value: u32,
    ) -> Result<()> {
        self.check_copy_bounds(staging_offset, dst_offset, bytes)?;
        if fence_slot >= self.fence_slots {
            return Err(anyhow!(
                "fence slot {} out of range for {} slots",
                fence_slot,
                self.fence_slots
            ));
        }
        self.sdma.push_copy(
            self.staging.va() + staging_offset as u64,
            self.dst.va() + dst_offset as u64,
            bytes,
        );
        self.sdma.push_fence(self.fence_va(fence_slot), fence_value);
        self.sdma.commit();
        Ok(())
    }

    pub fn copy_staging_pieces_to_dst_fenced_async(
        &mut self,
        pieces: &[(usize, usize, usize)],
        fence_slot: usize,
        fence_value: u32,
    ) -> Result<()> {
        if fence_slot >= self.fence_slots {
            return Err(anyhow!(
                "fence slot {} out of range for {} slots",
                fence_slot,
                self.fence_slots
            ));
        }
        if pieces.is_empty() {
            self.sdma.push_fence(self.fence_va(fence_slot), fence_value);
            self.sdma.commit();
            return Ok(());
        }
        for &(staging_offset, dst_offset, bytes) in pieces {
            self.check_copy_bounds(staging_offset, dst_offset, bytes)?;
            self.sdma.push_copy(
                self.staging.va() + staging_offset as u64,
                self.dst.va() + dst_offset as u64,
                bytes,
            );
        }
        self.sdma.push_fence(self.fence_va(fence_slot), fence_value);
        self.sdma.commit();
        Ok(())
    }

    pub fn wait_fence(&self, fence_slot: usize, value: u32, timeout: Duration) -> Result<()> {
        if fence_slot >= self.fence_slots {
            return Err(anyhow!(
                "fence slot {} out of range for {} slots",
                fence_slot,
                self.fence_slots
            ));
        }
        let start = Instant::now();
        let offset = fence_slot * 4;
        loop {
            let got = self.fences.read_u32(offset);
            if got >= value {
                std::sync::atomic::fence(std::sync::atomic::Ordering::Acquire);
                return Ok(());
            }
            if start.elapsed() > timeout {
                return Err(anyhow!(
                    "SDMA fence timeout on slot {fence_slot}: got {got}, want {value}"
                ));
            }
            std::hint::spin_loop();
        }
    }

    fn check_copy_bounds(
        &self,
        staging_offset: usize,
        dst_offset: usize,
        bytes: usize,
    ) -> Result<()> {
        if staging_offset
            .checked_add(bytes)
            .is_none_or(|end| end > self.staging_capacity)
            || dst_offset
                .checked_add(bytes)
                .is_none_or(|end| end > self.dst_capacity)
        {
            return Err(anyhow!(
                "reusable weight uploader copy out of bounds: staging_offset={} dst_offset={} bytes={} staging_capacity={} dst_capacity={}",
                staging_offset,
                dst_offset,
                bytes,
                self.staging_capacity,
                self.dst_capacity
            ));
        }
        Ok(())
    }

    fn fence_va(&self, fence_slot: usize) -> u64 {
        self.fences.va() + (fence_slot * 4) as u64
    }

    pub fn sample3(&mut self, len: usize) -> Result<(u8, u8, u8)> {
        if len == 0 || len > self.dst_capacity {
            return Err(anyhow!(
                "invalid reusable weight uploader sample length {len} for dst capacity {}",
                self.dst_capacity
            ));
        }
        let s = unsafe { self.dst.as_mut_slice() };
        Ok((s[0], s[len / 2], s[len - 1]))
    }

    pub fn read_dst_byte(&mut self, offset: usize) -> Result<u8> {
        if offset >= self.dst_capacity {
            return Err(anyhow!(
                "destination byte offset {} out of range for capacity {}",
                offset,
                self.dst_capacity
            ));
        }
        Ok(unsafe { self.dst.as_mut_slice()[offset] })
    }

    pub fn dst_va(&self) -> u64 {
        self.dst.va()
    }
}

pub fn materialize_slice_to_vram_sdma(
    dev: &GpuDevice,
    path: impl AsRef<Path>,
    plan: &TensorSlicePlan,
    timeout: Duration,
) -> Result<DeviceBuffer> {
    let bytes = materialize_slice_from_file(path, plan)?;
    upload_bytes_to_vram_sdma(dev, &bytes, timeout)
}

pub fn convert_qwen_rank_shard_safetensors(
    source_path: impl AsRef<Path>,
    output_path: impl AsRef<Path>,
    tp_rank: usize,
    tp_world: usize,
) -> Result<QwenRankShardConvertResult> {
    if tp_world == 0 {
        return Err(anyhow!("tensor-parallel world must be non-zero"));
    }
    if tp_rank >= tp_world {
        return Err(anyhow!(
            "tensor-parallel rank {tp_rank} out of range for world {tp_world}"
        ));
    }
    let source_path = source_path.as_ref();
    let output_path = output_path.as_ref();
    let source = SafetensorsShard::open(source_path)?;
    let source_file = File::open(source_path)
        .with_context(|| format!("opening source shard {}", source_path.display()))?;
    let mut metas = source.tensors.values().collect::<Vec<_>>();
    metas.sort_by_key(|meta| meta.file_offsets.0);

    let mut converted = Vec::with_capacity(metas.len());
    let mut source_bytes = 0u64;
    for meta in metas {
        source_bytes = source_bytes
            .checked_add(meta.byte_len())
            .ok_or_else(|| anyhow!("source byte total overflows"))?;
        match qwen_weight_placement(&meta.name) {
            QwenWeightPlacement::TensorParallel { axis } => {
                let plan = plan_tensor_parallel_slice(meta, axis, tp_rank, tp_world, None)?;
                converted.push(ConvertedTensor {
                    name: meta.name.clone(),
                    dtype: meta.dtype.clone(),
                    shape: plan.local_shape.clone(),
                    data: materialize_slice_from_file_handle(&source_file, &plan)?,
                });
            }
            QwenWeightPlacement::Replicated => {
                converted.push(ConvertedTensor {
                    name: meta.name.clone(),
                    dtype: meta.dtype.clone(),
                    shape: meta.shape.clone(),
                    data: read_tensor_bytes(&source_file, meta)?,
                });
            }
            QwenWeightPlacement::ExpertWhole => {
                return Err(anyhow!(
                    "routed expert tensor {} requires explicit EP placement before rank-shard conversion",
                    meta.name
                ));
            }
        }
    }

    write_converted_safetensors(output_path, &converted)?;
    let parsed = SafetensorsShard::open(output_path)?;
    if parsed.tensors.len() != converted.len() {
        return Err(anyhow!(
            "converted shard parsed {} tensors, expected {}",
            parsed.tensors.len(),
            converted.len()
        ));
    }
    let shard_bytes = converted.iter().try_fold(0u64, |acc, tensor| {
        acc.checked_add(tensor.data.len() as u64)
            .ok_or_else(|| anyhow!("converted shard byte total overflows"))
    })?;
    let first_byte = converted
        .iter()
        .find_map(|tensor| tensor.data.first().copied())
        .unwrap_or(0);
    let last_byte = converted
        .iter()
        .rev()
        .find_map(|tensor| tensor.data.last().copied())
        .unwrap_or(0);
    Ok(QwenRankShardConvertResult {
        tensor_count: converted.len(),
        tp_rank,
        tp_world,
        source_bytes,
        shard_bytes,
        first_byte,
        last_byte,
    })
}

pub fn convert_qwen_rank_shards_from_index(
    index_path: impl AsRef<Path>,
    output_path: impl AsRef<Path>,
    tp_rank: usize,
    tp_world: usize,
) -> Result<QwenRankShardConvertResult> {
    if tp_world == 0 {
        return Err(anyhow!("tensor-parallel world must be non-zero"));
    }
    if tp_rank >= tp_world {
        return Err(anyhow!(
            "tensor-parallel rank {tp_rank} out of range for world {tp_world}"
        ));
    }
    let index_path = index_path.as_ref();
    let output_path = output_path.as_ref();
    let index = SafetensorsIndex::open(index_path)?;
    if index.weight_map.is_empty() {
        return Err(anyhow!("{} has an empty weight_map", index.path.display()));
    }

    let mut shard_paths = index.weight_map.values().cloned().collect::<Vec<_>>();
    shard_paths.sort();
    shard_paths.dedup();

    let mut shards = HashMap::new();
    for shard_path in &shard_paths {
        shards.insert(shard_path.clone(), SafetensorsShard::open(shard_path)?);
    }

    let mut entries = Vec::with_capacity(index.weight_map.len());
    let mut source_bytes = 0u64;
    for (name, shard_path) in &index.weight_map {
        let shard = shards
            .get(shard_path)
            .ok_or_else(|| anyhow!("index shard {} was not opened", shard_path.display()))?;
        let meta = shard.tensor(name)?.clone();
        source_bytes = source_bytes
            .checked_add(meta.byte_len())
            .ok_or_else(|| anyhow!("indexed source byte total overflows"))?;
        entries.push((shard_path.clone(), meta.file_offsets.0, meta));
    }
    check_safetensors_index_total_size(&index, source_bytes)?;
    entries.sort_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| a.1.cmp(&b.1))
            .then_with(|| a.2.name.cmp(&b.2.name))
    });

    let mut files = HashMap::new();
    for shard_path in &shard_paths {
        let file = File::open(shard_path)
            .with_context(|| format!("opening index shard {}", shard_path.display()))?;
        files.insert(shard_path.clone(), file);
    }

    let mut converted = Vec::with_capacity(entries.len());
    for (shard_path, _, meta) in entries {
        let source_file = files
            .get(&shard_path)
            .ok_or_else(|| anyhow!("index shard {} file was not opened", shard_path.display()))?;
        match qwen_weight_placement(&meta.name) {
            QwenWeightPlacement::TensorParallel { axis } => {
                let plan = plan_tensor_parallel_slice(&meta, axis, tp_rank, tp_world, None)?;
                converted.push(ConvertedTensor {
                    name: meta.name,
                    dtype: meta.dtype,
                    shape: plan.local_shape.clone(),
                    data: materialize_slice_from_file_handle(source_file, &plan)?,
                });
            }
            QwenWeightPlacement::Replicated => {
                let data = read_tensor_bytes(source_file, &meta)?;
                converted.push(ConvertedTensor {
                    name: meta.name,
                    dtype: meta.dtype,
                    shape: meta.shape,
                    data,
                });
            }
            QwenWeightPlacement::ExpertWhole => {
                return Err(anyhow!(
                    "routed expert tensor {} requires explicit EP placement before rank-shard conversion",
                    meta.name
                ));
            }
        }
    }

    write_converted_safetensors(output_path, &converted)?;
    let parsed = SafetensorsShard::open(output_path)?;
    if parsed.tensors.len() != converted.len() {
        return Err(anyhow!(
            "converted shard parsed {} tensors, expected {}",
            parsed.tensors.len(),
            converted.len()
        ));
    }
    let shard_bytes = converted.iter().try_fold(0u64, |acc, tensor| {
        acc.checked_add(tensor.data.len() as u64)
            .ok_or_else(|| anyhow!("converted shard byte total overflows"))
    })?;
    let first_byte = converted
        .iter()
        .find_map(|tensor| tensor.data.first().copied())
        .unwrap_or(0);
    let last_byte = converted
        .iter()
        .rev()
        .find_map(|tensor| tensor.data.last().copied())
        .unwrap_or(0);
    Ok(QwenRankShardConvertResult {
        tensor_count: converted.len(),
        tp_rank,
        tp_world,
        source_bytes,
        shard_bytes,
        first_byte,
        last_byte,
    })
}

pub fn selftest_qwen_rank_shard_conversion(
    tp_rank: usize,
    tp_world: usize,
) -> Result<QwenRankShardConvertResult> {
    let source = std::env::temp_dir().join(format!(
        "mainarch-qwen-rank-shard-convert-source-{}.safetensors",
        std::process::id()
    ));
    let output = std::env::temp_dir().join(format!(
        "mainarch-qwen-rank-shard-convert-output-{}.safetensors",
        std::process::id()
    ));
    let result = (|| -> Result<QwenRankShardConvertResult> {
        write_qwen_rank_shard_selftest_source(&source)?;
        let result = convert_qwen_rank_shard_safetensors(&source, &output, tp_rank, tp_world)?;
        validate_qwen_rank_shard_conversion(&source, &output, tp_rank, tp_world)?;
        Ok(result)
    })();
    let _ = fs::remove_file(source);
    let _ = fs::remove_file(output);
    result
}

pub fn selftest_qwen_rank_shard_index_conversion(
    tp_rank: usize,
    tp_world: usize,
) -> Result<QwenRankShardConvertResult> {
    let dir = std::env::temp_dir().join(format!(
        "mainarch-qwen-rank-shard-index-convert-{}",
        std::process::id()
    ));
    let output = dir.join("tp-rank.safetensors");
    let result = (|| -> Result<QwenRankShardConvertResult> {
        let index = write_qwen_rank_shard_selftest_index_source(&dir)?;
        let result = convert_qwen_rank_shards_from_index(&index, &output, tp_rank, tp_world)?;
        validate_qwen_rank_shard_index_conversion(&index, &output, tp_rank, tp_world)?;
        Ok(result)
    })();
    let _ = fs::remove_dir_all(dir);
    result
}

pub fn preflight_qwen_checkpoint(
    config_path: impl AsRef<Path>,
    index_path: impl AsRef<Path>,
    tp_world: usize,
) -> Result<QwenCheckpointPreflightResult> {
    let config_path = config_path.as_ref();
    let index = SafetensorsIndex::open(index_path)?;
    if index.weight_map.is_empty() {
        return Err(anyhow!("{} has an empty weight_map", index.path.display()));
    }
    let names = index
        .weight_map
        .keys()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let indexed_bytes = index
        .metadata
        .get("total_size")
        .map(|s| {
            s.parse::<u64>()
                .with_context(|| format!("parsing {} metadata.total_size", index.path.display()))
        })
        .transpose()?;
    preflight_qwen_checkpoint_names(config_path, &index.path, &names, indexed_bytes, tp_world)
}

pub fn preflight_qwen_checkpoint_file(
    config_path: impl AsRef<Path>,
    source_path: impl AsRef<Path>,
    tp_world: usize,
) -> Result<QwenCheckpointPreflightResult> {
    let config_path = config_path.as_ref();
    let source = SafetensorsShard::open(source_path)?;
    if source.tensors.is_empty() {
        return Err(anyhow!("{} has no tensors", source.path.display()));
    }
    let names = source
        .tensors
        .keys()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let source_bytes = source.tensors.values().try_fold(0u64, |acc, meta| {
        acc.checked_add(meta.byte_len())
            .ok_or_else(|| anyhow!("{} tensor byte total overflows", source.path.display()))
    })?;
    preflight_qwen_checkpoint_names(
        config_path,
        &source.path,
        &names,
        Some(source_bytes),
        tp_world,
    )
}

fn preflight_qwen_checkpoint_names(
    config_path: &Path,
    artifact_path: &Path,
    names: &HashSet<&str>,
    source_bytes: Option<u64>,
    tp_world: usize,
) -> Result<QwenCheckpointPreflightResult> {
    if tp_world == 0 {
        return Err(anyhow!("tensor-parallel world must be non-zero"));
    }
    let config = QwenCheckpointConfig::open(config_path)?;
    if !config.model_type.starts_with("qwen") {
        return Err(anyhow!(
            "config model_type={} is not a Qwen-family model",
            config.model_type
        ));
    }
    if config.is_moe {
        return Err(anyhow!(
            "config model_type={} has MoE fields; explicit EP placement is required before Qwen preflight can pass",
            config.model_type
        ));
    }
    if config.num_attention_heads == 0 || config.num_key_value_heads == 0 {
        return Err(anyhow!(
            "Qwen config head counts must be non-zero, got attention={} kv={}",
            config.num_attention_heads,
            config.num_key_value_heads
        ));
    }
    if config.num_attention_heads % tp_world as u64 != 0 {
        return Err(anyhow!(
            "num_attention_heads={} is not divisible by tp_world={}",
            config.num_attention_heads,
            tp_world
        ));
    }
    if config.num_key_value_heads >= tp_world as u64 {
        if config.num_key_value_heads % tp_world as u64 != 0 {
            return Err(anyhow!(
                "num_key_value_heads={} is >= tp_world={} but not divisible by tp_world",
                config.num_key_value_heads,
                tp_world
            ));
        }
    } else if (tp_world as u64) % config.num_key_value_heads != 0 {
        return Err(anyhow!(
            "num_key_value_heads={} is < tp_world={} but tp_world is not divisible by num_key_value_heads",
            config.num_key_value_heads,
            tp_world
        ));
    }

    let expert_tensors = names
        .iter()
        .filter(|name| is_qwen_routed_expert_weight(name))
        .count();
    if expert_tensors != 0 {
        return Err(anyhow!(
            "{} contains {} routed expert tensors; explicit EP placement is required before Qwen preflight can pass",
            artifact_path.display(),
            expert_tensors
        ));
    }

    let mut missing = Vec::new();
    require_weight(&names, "model.embed_tokens.weight", &mut missing);
    require_weight(&names, "model.norm.weight", &mut missing);
    if !config.tie_word_embeddings {
        require_weight(&names, "lm_head.weight", &mut missing);
    }
    for layer in 0..config.num_hidden_layers {
        let prefix = format!("model.layers.{layer}");
        for suffix in [
            "self_attn.q_proj.weight",
            "self_attn.k_proj.weight",
            "self_attn.v_proj.weight",
            "self_attn.o_proj.weight",
            "self_attn.q_norm.weight",
            "self_attn.k_norm.weight",
            "input_layernorm.weight",
            "post_attention_layernorm.weight",
            "mlp.gate_proj.weight",
            "mlp.up_proj.weight",
            "mlp.down_proj.weight",
        ] {
            require_weight(&names, &format!("{prefix}.{suffix}"), &mut missing);
        }
    }
    if !missing.is_empty() {
        return Err(anyhow!(
            "{} is missing {} required dense Qwen tensors, first missing {}",
            artifact_path.display(),
            missing.len(),
            missing[0]
        ));
    }

    let mut tensor_parallel_tensors = 0usize;
    let mut replicated_tensors = 0usize;
    for name in names {
        match qwen_weight_placement(name) {
            QwenWeightPlacement::TensorParallel { .. } => tensor_parallel_tensors += 1,
            QwenWeightPlacement::Replicated => replicated_tensors += 1,
            QwenWeightPlacement::ExpertWhole => unreachable!("expert tensors were rejected above"),
        }
    }
    Ok(QwenCheckpointPreflightResult {
        model_type: config.model_type,
        num_hidden_layers: config.num_hidden_layers,
        num_attention_heads: config.num_attention_heads,
        num_key_value_heads: config.num_key_value_heads,
        tie_word_embeddings: config.tie_word_embeddings,
        tp_world,
        tensor_count: names.len(),
        tensor_parallel_tensors,
        replicated_tensors,
        lm_head_present: names.contains("lm_head.weight"),
        indexed_bytes: source_bytes,
    })
}

