/// End-to-end loader substrate selftest: SafeTensors metadata -> TP slice gather
/// -> host staging -> raw KFD SDMA upload -> VRAM readback.
pub fn selftest_safetensors_sdma_upload(node_id: u32) -> Result<WeightUploadSelftestResult> {
    let dev = GpuDevice::open(node_id)?;
    let tensor = "model.layers.0.self_attn.o_proj.weight";
    let header = format!(r#"{{"{tensor}":{{"dtype":"U8","shape":[4,8],"data_offsets":[0,32]}}}}"#);
    let mut bytes = Vec::new();
    bytes.extend_from_slice(&(header.len() as u64).to_le_bytes());
    bytes.extend_from_slice(header.as_bytes());
    bytes.extend(0u8..32u8);

    let path = std::env::temp_dir().join(format!(
        "mainarch-weight-upload-{}-{}.safetensors",
        std::process::id(),
        node_id
    ));
    fs::write(&path, &bytes).with_context(|| format!("writing {}", path.display()))?;
    let cleanup_path = path.clone();
    let result = (|| -> Result<WeightUploadSelftestResult> {
        let shard = SafetensorsShard::parse(path.clone(), &bytes)?;
        let meta = shard.tensor(tensor)?;
        let plan = plan_tensor_parallel_slice(meta, 1, 1, 4, None)?;
        let local = materialize_slice_from_file(&path, &plan)?;
        // Axis-1, rank 1/4 over shape [4,8] selects cols [2,4) from every row.
        let expected = vec![2, 3, 10, 11, 18, 19, 26, 27];
        if local != expected {
            return Err(anyhow!(
                "selftest local slice mismatch: {local:?} != {expected:?}"
            ));
        }
        let mut dst = upload_bytes_to_vram_sdma(&dev, &local, Duration::from_secs(5))?;
        let got = unsafe { dst.as_mut_slice()[..local.len()].to_vec() };
        if got != local {
            return Err(anyhow!(
                "selftest VRAM upload mismatch: {got:?} != {local:?}"
            ));
        }
        Ok(WeightUploadSelftestResult {
            node_id,
            bytes: local.len(),
            first_byte: got[0],
            last_byte: got[got.len() - 1],
        })
    })();
    let _ = fs::remove_file(cleanup_path);
    result
}

