    #[test]
    fn parses_safetensors_offsets_as_absolute_file_ranges() {
        let header = r#"{"model.layers.0.self_attn.q_proj.weight":{"dtype":"F16","shape":[4,8],"data_offsets":[0,64]},"__metadata__":{"format":"pt"}}"#;
        let bytes = safetensors_bytes(header, 64);
        let shard =
            SafetensorsShard::parse(PathBuf::from("model-00001-of-00002.safetensors"), &bytes)
                .unwrap();
        let t = shard
            .tensor("model.layers.0.self_attn.q_proj.weight")
            .unwrap();
        assert_eq!(t.dtype, "F16");
        assert_eq!(t.shape, vec![4, 8]);
        assert_eq!(t.data_offsets, (0, 64));
        assert_eq!(
            t.file_offsets,
            (8 + header.len() as u64, 8 + header.len() as u64 + 64)
        );
    }

    #[test]
