    #[test]
    fn sharded_index_resolves_model_checkpoint_binding_plan_keys() {
        let index = r#"{"metadata":{"total_size":256},"weight_map":{"model.layers.0.self_attn.q_proj.weight":"model-00001-of-00002.safetensors","model.layers.0.mlp.experts.0.gate_proj.weight":"model-00001-of-00002.safetensors","model.layers.0.mlp.experts.1.gate_proj.weight":"model-00002-of-00002.safetensors","model.extra.weight":"model-00002-of-00002.safetensors"}}"#;
        let idx =
            SafetensorsIndex::parse(PathBuf::from("/ckpt/model.safetensors.index.json"), index)
                .unwrap();
        let q_proj = checkpoint_binding(
            "layers.0.q_proj.weight",
            "model.layers.0.self_attn.q_proj.weight",
            vec![4, 8],
        );
        let packed_gate = checkpoint_binding(
            "layers.0.experts.gate.weight",
            "model.layers.0.mlp.experts.*.gate_proj.weight",
            vec![2, 4, 8],
        );
        let missing = checkpoint_binding(
            "layers.0.o_proj.weight",
            "model.layers.0.self_attn.o_proj.weight",
            vec![8, 4],
        );
        let total_checkpoint_bytes =
            q_proj.storage_bytes + packed_gate.storage_bytes + missing.storage_bytes;
        let plan = ModelCheckpointBindingPlan {
            entries: vec![q_proj, packed_gate, missing],
            missing_weight_tensors: Vec::new(),
            total_checkpoint_bytes,
        };

        let resolution = idx.resolve_model_checkpoint_bindings(&plan).unwrap();
        assert_eq!(
            resolution
                .resolved_entry_for("layers.0.q_proj.weight")
                .unwrap()
                .matched_checkpoint_keys,
            vec!["model.layers.0.self_attn.q_proj.weight".to_string()]
        );
        assert_eq!(
            resolution
                .resolved_entry_for("layers.0.experts.gate.weight")
                .unwrap()
                .matched_checkpoint_keys,
            vec![
                "model.layers.0.mlp.experts.0.gate_proj.weight".to_string(),
                "model.layers.0.mlp.experts.1.gate_proj.weight".to_string()
            ]
        );
        assert_eq!(
            resolution.missing_checkpoint_entries,
            vec![MissingCheckpointEntry {
                tensor: TensorRef::from("layers.0.o_proj.weight"),
                checkpoint_key: "model.layers.0.self_attn.o_proj.weight".to_string(),
            }]
        );
        assert_eq!(
            resolution.unmatched_checkpoint_keys,
            vec!["model.extra.weight".to_string()]
        );
    }

    #[test]
    fn sharded_index_validates_model_checkpoint_metadata_across_shards() {
        let dir = std::env::temp_dir().join(format!(
            "mainarch-index-metadata-valid-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let shard0 = dir.join("model-00001-of-00002.safetensors");
        let shard1 = dir.join("model-00002-of-00002.safetensors");
        let shard0_header = r#"{"model.layers.0.self_attn.q_proj.weight":{"dtype":"F16","shape":[4,8],"data_offsets":[0,64]},"model.layers.0.mlp.experts.0.gate_proj.weight":{"dtype":"F16","shape":[2,4],"data_offsets":[64,80]}}"#;
        let shard1_header = r#"{"model.layers.0.mlp.experts.1.gate_proj.weight":{"dtype":"F16","shape":[2,4],"data_offsets":[0,16]},"model.extra.weight":{"dtype":"F16","shape":[1],"data_offsets":[16,18]}}"#;
        fs::write(&shard0, safetensors_bytes(shard0_header, 80)).unwrap();
        fs::write(&shard1, safetensors_bytes(shard1_header, 18)).unwrap();
        let index = r#"{"metadata":{"total_size":98},"weight_map":{"model.layers.0.self_attn.q_proj.weight":"model-00001-of-00002.safetensors","model.layers.0.mlp.experts.0.gate_proj.weight":"model-00001-of-00002.safetensors","model.layers.0.mlp.experts.1.gate_proj.weight":"model-00002-of-00002.safetensors","model.extra.weight":"model-00002-of-00002.safetensors"}}"#;
        let idx = SafetensorsIndex::parse(dir.join("model.safetensors.index.json"), index).unwrap();
        let q_proj = checkpoint_binding(
            "layers.0.q_proj.weight",
            "model.layers.0.self_attn.q_proj.weight",
            vec![4, 8],
        );
        let packed_gate = checkpoint_binding(
            "layers.0.experts.gate.weight",
            "model.layers.0.mlp.experts.*.gate_proj.weight",
            vec![2, 2, 4],
        );
        let plan = ModelCheckpointBindingPlan {
            total_checkpoint_bytes: q_proj.storage_bytes + packed_gate.storage_bytes,
            entries: vec![q_proj, packed_gate],
            missing_weight_tensors: Vec::new(),
        };

        let validation = idx.validate_model_checkpoint_bindings(&plan).unwrap();
        validation.assert_fully_valid().unwrap();
        assert_eq!(
            validation.opened_shards,
            vec![shard0.clone(), shard1.clone()]
        );
        assert!(validation.missing_shards.is_empty());
        assert!(validation.mismatches.is_empty());
        assert_eq!(validation.checked_entries.len(), 2);
        assert_eq!(
            validation
                .checked_entries
                .iter()
                .map(|entry| entry.actual_storage_bytes)
                .sum::<u64>(),
            96
        );
        assert_eq!(
            validation.resolution.unmatched_checkpoint_keys,
            vec!["model.extra.weight".to_string()]
        );

        let _ = fs::remove_dir_all(dir);
    }

