    #[test]
    fn sharded_index_reports_missing_shards_and_metadata_mismatches() {
        let dir = std::env::temp_dir().join(format!(
            "mainarch-index-metadata-invalid-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        let shard0 = dir.join("model-00001-of-00002.safetensors");
        let missing_shard = dir.join("model-00002-of-00002.safetensors");
        let shard0_header = r#"{"model.layers.0.self_attn.q_proj.weight":{"dtype":"BF16","shape":[8,4],"data_offsets":[0,64]}}"#;
        fs::write(&shard0, safetensors_bytes(shard0_header, 64)).unwrap();
        let index = r#"{"metadata":{"total_size":80},"weight_map":{"model.layers.0.self_attn.q_proj.weight":"model-00001-of-00002.safetensors","model.layers.0.mlp.experts.0.gate_proj.weight":"model-00002-of-00002.safetensors"}}"#;
        let idx = SafetensorsIndex::parse(dir.join("model.safetensors.index.json"), index).unwrap();
        let q_proj = checkpoint_binding(
            "layers.0.q_proj.weight",
            "model.layers.0.self_attn.q_proj.weight",
            vec![4, 8],
        );
        let packed_gate = checkpoint_binding(
            "layers.0.experts.gate.weight",
            "model.layers.0.mlp.experts.*.gate_proj.weight",
            vec![1, 2, 4],
        );
        let plan = ModelCheckpointBindingPlan {
            total_checkpoint_bytes: q_proj.storage_bytes + packed_gate.storage_bytes,
            entries: vec![q_proj, packed_gate],
            missing_weight_tensors: Vec::new(),
        };

        let validation = idx.validate_model_checkpoint_bindings(&plan).unwrap();
        assert_eq!(validation.opened_shards, vec![shard0]);
        assert_eq!(validation.missing_shards, vec![missing_shard]);
        let err = validation.assert_fully_valid().unwrap_err().to_string();
        assert!(err.contains("missing shard file"));
        let reasons = validation
            .mismatches
            .iter()
            .map(|mismatch| mismatch.reason.as_str())
            .collect::<Vec<_>>();
        assert!(reasons
            .iter()
            .any(|reason| reason.contains("dtype mismatch")));
        assert!(reasons
            .iter()
            .any(|reason| reason.contains("shape mismatch")));

        let _ = fs::remove_dir_all(dir);
    }

