    #[test]
    fn safetensors_shard_refuses_payload_bindings_for_invalid_metadata() {
        let header =
            r#"{"model.embed_tokens.weight":{"dtype":"BF16","shape":[2,8],"data_offsets":[0,32]}}"#;
        let bytes = safetensors_bytes(header, 32);
        let shard =
            SafetensorsShard::parse(PathBuf::from("model-00001-of-00001.safetensors"), &bytes)
                .unwrap();
        let embed = checkpoint_binding(
            "embed_tokens.weight",
            "model.embed_tokens.weight",
            vec![4, 4],
        );
        let plan = ModelCheckpointBindingPlan {
            total_checkpoint_bytes: embed.storage_bytes,
            entries: vec![embed],
            missing_weight_tensors: Vec::new(),
        };

        let err = shard
            .runtime_checkpoint_payload_bindings(&plan)
            .unwrap_err()
            .to_string();
        assert!(err.contains("mismatch"));
        assert!(err.contains("dtype mismatch") || err.contains("shape mismatch"));
    }

    #[test]
    fn safetensors_shard_reports_model_checkpoint_metadata_mismatches() {
        let header = r#"{"model.layers.0.self_attn.q_proj.weight":{"dtype":"F16","shape":[4,8],"data_offsets":[0,64]},"model.layers.0.mlp.experts.0.gate_proj.weight":{"dtype":"F16","shape":[2,4],"data_offsets":[64,80]}}"#;
        let bytes = safetensors_bytes(header, 80);
        let shard =
            SafetensorsShard::parse(PathBuf::from("model-00001-of-00001.safetensors"), &bytes)
                .unwrap();
        let mut q_proj = checkpoint_binding(
            "layers.0.q_proj.weight",
            "model.layers.0.self_attn.q_proj.weight",
            vec![8, 4],
        );
        q_proj.dtype = DType::Bf16;
        let packed_gate = checkpoint_binding(
            "layers.0.experts.gate.weight",
            "model.layers.0.mlp.experts.*.gate_proj.weight",
            vec![2, 2, 4],
        );
        let plan = ModelCheckpointBindingPlan {
            total_checkpoint_bytes: q_proj.storage_bytes + packed_gate.storage_bytes,
            entries: vec![q_proj, packed_gate],
            missing_weight_tensors: Vec::new(),
        };

        let validation = shard.validate_model_checkpoint_bindings(&plan).unwrap();
        let err = validation.assert_fully_valid().unwrap_err();
        assert!(err.to_string().contains("mismatch"));
        let reasons = validation
            .mismatches
            .iter()
            .map(|mismatch| mismatch.reason.as_str())
            .collect::<Vec<_>>();
        assert!(reasons
            .iter()
            .any(|reason| reason.contains("dtype mismatch")));
        assert!(reasons
            .iter()
            .any(|reason| reason.contains("shape mismatch")));
        assert!(reasons
            .iter()
            .any(|reason| reason.contains("wildcard matched 1 checkpoint key(s), expected 2")));
        assert!(reasons
            .iter()
            .any(|reason| reason.contains("storage byte mismatch")));
    }

