    #[test]
    fn converts_qwen_rank_shard_byte_exact() {
        let source = std::env::temp_dir().join(format!(
            "mainarch-rank-shard-source-test-{}.safetensors",
            std::process::id()
        ));
        let output = std::env::temp_dir().join(format!(
            "mainarch-rank-shard-output-test-{}.safetensors",
            std::process::id()
        ));
        write_qwen_rank_shard_selftest_source(&source).unwrap();
        let result = convert_qwen_rank_shard_safetensors(&source, &output, 1, 2).unwrap();
        validate_qwen_rank_shard_conversion(&source, &output, 1, 2).unwrap();
        let shard = SafetensorsShard::open(&output).unwrap();
        let q = shard
            .tensor("model.layers.0.self_attn.q_proj.weight")
            .unwrap();
        let o = shard
            .tensor("model.layers.0.self_attn.o_proj.weight")
            .unwrap();
        let n = shard
            .tensor("model.layers.0.input_layernorm.weight")
            .unwrap();
        assert_eq!(result.tensor_count, 3);
        assert_eq!(result.source_bytes, 36);
        assert_eq!(result.shard_bytes, 20);
        assert_eq!(q.shape, vec![2, 4]);
        assert_eq!(o.shape, vec![2, 4]);
        assert_eq!(n.shape, vec![4]);
        let file = File::open(&output).unwrap();
        assert_eq!(
            read_tensor_bytes(&file, q).unwrap(),
            (8u8..16u8).collect::<Vec<_>>()
        );
        assert_eq!(
            read_tensor_bytes(&file, o).unwrap(),
            vec![20, 21, 22, 23, 28, 29, 30, 31]
        );
        assert_eq!(
            read_tensor_bytes(&file, n).unwrap(),
            (32u8..36u8).collect::<Vec<_>>()
        );
        let _ = fs::remove_file(source);
        let _ = fs::remove_file(output);
    }

    #[test]
    fn converts_qwen_rank_shard_from_index_byte_exact() {
        let dir = std::env::temp_dir().join(format!(
            "mainarch-rank-shard-index-test-{}",
            std::process::id()
        ));
        let output = dir.join("tp-rank.safetensors");
        let index = write_qwen_rank_shard_selftest_index_source(&dir).unwrap();
        let result = convert_qwen_rank_shards_from_index(&index, &output, 1, 2).unwrap();
        validate_qwen_rank_shard_index_conversion(&index, &output, 1, 2).unwrap();
        let shard = SafetensorsShard::open(&output).unwrap();
        let q = shard
            .tensor("model.layers.0.self_attn.q_proj.weight")
            .unwrap();
        let o = shard
            .tensor("model.layers.0.self_attn.o_proj.weight")
            .unwrap();
        let n = shard
            .tensor("model.layers.0.input_layernorm.weight")
            .unwrap();
        assert_eq!(result.tensor_count, 3);
        assert_eq!(result.source_bytes, 36);
        assert_eq!(result.shard_bytes, 20);
        assert_eq!(q.shape, vec![2, 4]);
        assert_eq!(o.shape, vec![2, 4]);
        assert_eq!(n.shape, vec![4]);
        let file = File::open(&output).unwrap();
        assert_eq!(
            read_tensor_bytes(&file, q).unwrap(),
            (8u8..16u8).collect::<Vec<_>>()
        );
        assert_eq!(
            read_tensor_bytes(&file, o).unwrap(),
            vec![20, 21, 22, 23, 28, 29, 30, 31]
        );
        assert_eq!(
            read_tensor_bytes(&file, n).unwrap(),
            (32u8..36u8).collect::<Vec<_>>()
        );
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn preflights_qwen_checkpoint_contract() {
        let result = selftest_qwen_checkpoint_preflight(2).unwrap();
        assert_eq!(result.model_type, "qwen3");
        assert_eq!(result.num_hidden_layers, 1);
        assert_eq!(result.num_attention_heads, 4);
        assert_eq!(result.num_key_value_heads, 2);
        assert!(!result.tie_word_embeddings);
        assert_eq!(result.tp_world, 2);
        assert_eq!(result.tensor_count, 14);
        assert_eq!(result.tensor_parallel_tensors, 9);
        assert_eq!(result.replicated_tensors, 5);
        assert!(result.lm_head_present);
        assert_eq!(result.indexed_bytes, Some(226));
    }

    #[test]
    fn converts_qwen_checkpoint_rank_shard_after_preflight() {
        let result = selftest_qwen_checkpoint_rank_shard_conversion(1, 2).unwrap();
        assert_eq!(result.preflight.model_type, "qwen3");
        assert_eq!(result.preflight.tensor_count, 14);
        assert_eq!(result.conversion.tensor_count, 14);
        assert_eq!(result.conversion.tp_rank, 1);
        assert_eq!(result.conversion.tp_world, 2);
        assert_eq!(result.conversion.source_bytes, 226);
        assert_eq!(result.conversion.shard_bytes, 122);
        assert_eq!(result.conversion.first_byte, 0);
        assert_eq!(result.conversion.last_byte, 13);
    }

